// Класс логики калькулятора
class Calculator {
  constructor() {
    this.result = 0;
  }

  // Методы операций
  add(a, b) { return a + b; }
  subtract(a, b) { return a - b; }
  multiply(a, b) { return a * b; }

  // Деление — требует защиты
  divide(a, b) {
    if (b === 0) throw new Error("Деление на ноль");
    return a / b;
  }

  // Вычисление через dispatch
  calculate(a, b, operator) {
    const methods = {
      "+": this.add,
      "-": this.subtract,
      "*": this.multiply,
      "/": this.divide
    };
    const method = methods[operator];
    if (!method) throw new Error("Неизвестная операция");
    return method(a, b);
  }
}

// Логика (класс)
const calc = new Calculator();

// Интерфейс (DOM)
const display = document.querySelector("#display");
const btns = document.querySelectorAll(".btn");

btns.forEach(btn => {
  btn.addEventListener("click", () => {
    const operator = btn.dataset.operator;
    const a = Number(display.value);

    try {
      const result = calc.calculate(a, 10, operator);
      display.value = result;  // показываем результат
    } catch (e) {
      display.value = "Error";  // показываем ошибку
    }
  });
});

const calcPanel = document.querySelector(".calc-panel");

// Один обработчик для всех кнопок
calcPanel.addEventListener("click", (event) => {
  const btn = event.target.closest(".btn");
  if (!btn) return;  // кликнули не по кнопке

  const action = btn.dataset.action;
  const value = btn.dataset.value;

  if (action === "operator") {
    handleOperator(value);  // +, -, *, /
  } else if (action === "digit") {
    handleDigit(value);     // 0-9
  } else if (action === "clear") {
    handleClear();
  }
});

