// Расширение Calculator
class Calculator {
  // ... существующие методы

  // Новая операция: процент
  percent(a, b) {
    return a * b / 100;
  }

  // Возведение в степень
  power(a, b) {
    return Math.pow(a, b);
  }

  // История операций
  #history = [];

  record(a, b, operator, result) {
    this.#history.push({ a, b, operator, result });
  }

  getHistory() {
    return [...this.#history];  // копия, не оригинал
  }
}

